# -*- coding: utf-8 -*-
"""Imagine-кадры первых 5 минут: каждый промпт n=2, отбор глазами. Правила: деталь новая и чистая, свет схемой, палитра с замком, 16:9."""
import sys, io, os, time, json
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8")
HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "first5", "imagine"); os.makedirs(OUT, exist_ok=True)
import xai

CLEAN = "Всё железо новое, только с завода, безупречно чистое, без пыли и следов. "
P = {
 # кадр 1 — правила стенда: две платы рядом, ценники
 "f01_stand": "СУБЪЕКТ: открытый тестовый стенд: процессор без крышки под медным водоблоком прямого контакта, прозрачные трубки кастомного контура. Рядом на столе лежат две материнские платы: одна крупная чёрная с массивными радиаторами и подсветкой, вторая компактная простая без радиаторов-монолитов; у каждой маленькая пустая бумажная бирка на нитке. " + CLEAN + "СВЕТ: строго один источник: холодный белый софтбокс слева сверху под сорок пять градусов, мягкий, 5600K, заполняющего света нет, правая часть кадра уходит в глубокую нейтральную тень. ПЕРЕДНИЙ ПЛАН: край столешницы из тёмного матового металла. СРЕДНИЙ ПЛАН: стенд и две платы. ДАЛЬНИЙ ПЛАН: тёмная стена мастерской размыта до мягкой мути. ПАЛИТРА строго из четырёх цветов и только из них: графитовый чёрный, матовое серебро, медь, холодный белый. Других цветов в кадре нет. Других надписей в кадре нет. КАДР: общий план сверху под тридцать градусов, горизонтальный кадр 16:9. Фотография.",
 # кадр 2 — судья и свидетели (ирония)
 "f02_judge": "СУБЪЕКТ: деревянный судейский молоток лежит на чёрной матовой подставке рядом с одним процессором без крышки, кристалл открыт и блестит. Больше предметов нет. " + CLEAN + "СВЕТ: строго один источник: жёсткий холодный луч сверху справа под шестьдесят градусов, 5000K, резкая граница тени, заполняющего света нет, фон уходит в чёрное. ПЕРЕДНИЙ ПЛАН: край подставки крупно. ДАЛЬНИЙ ПЛАН: чёрная пустота. ПАЛИТРА строго из трёх цветов и только из них: чёрный, тёмное дерево, холодное серебро. Других цветов в кадре нет. Других надписей в кадре нет. КАДР: крупный план, камера на уровне стола, предметы занимают правую половину кадра, слева свободная тёмная зона, горизонтальный кадр 16:9. Фотография.",
 # кадр 4 — матчасть: навигация звездолёта (мотив второй серии)
 "f04_starship": "Цифровая живопись, кинематографичная. СЦЕНА: тёмная навигационная рубка звездолёта, над пультом парит голографическая кривая: тонкая светящаяся линия изгибается в пространстве, вокруг неё четыре тонкие оси с подписями-символами без букв. Один пилот в кресле спиной к зрителю, смотрит на кривую. СВЕТ: строго один источник: сама голограмма, холодный голубой 8000K, мягкий, освещает спинку кресла и пульт снизу, заполняющего света нет, остальная рубка тонет в черноте. ПЕРЕДНИЙ ПЛАН: край пульта с погашенными кнопками. СРЕДНИЙ ПЛАН: кресло и голограмма. ДАЛЬНИЙ ПЛАН: панорамное окно, за ним звёзды выцвели в бледную дымку. ПАЛИТРА строго из трёх цветов и только из них: чёрный, холодный голубой, тусклое серебро. Других цветов в кадре нет. Других надписей в кадре нет. КАДР: общий план из-за спины пилота, горизонтальный кадр 16:9.",
 # кадр 5 — музей настроек биоса (балласт, музей и ловушки)
 "f05_museum": "СЦЕНА: длинный тёмный музейный зал, вдоль стен ряды стеклянных витрин с подсветкой, в каждой витрине на бархате лежит по одной маленькой латунной табличке-переключателю. Витрин очень много, ряд уходит в глубину. Над входом в зал вывеска кириллицей крупными ровными заглавными буквами: «МУЗЕЙ». Буквы чёткие, читаемые, без искажений, без лишних символов. Других надписей в кадре нет. СВЕТ: строго один тип источника: подсветка внутри витрин, холодная белая 5000K, мягкая, заполняющего света нет, пол и потолок уходят в черноту. ПЕРЕДНИЙ ПЛАН: ближайшая витрина крупно и резко. СРЕДНИЙ ПЛАН: ряд витрин. ДАЛЬНИЙ ПЛАН: конец зала выцвел в бледную дымку и почти потерял контраст. ПАЛИТРА строго из трёх цветов и только из них: чёрный, холодный белый, латунь. Других цветов в кадре нет. КАДР: общий план по центральному проходу, камера на уровне глаз, горизонтальный кадр 16:9. Фотография.",
 # кадр 6 — флагманская плата крупно (обобщённая, не конкретная модель)
 "f06_vrm": "СУБЪЕКТ: макро фрагмента флагманской материнской платы: ряд массивных чёрных алюминиевых радиаторов питания с тонкими рёбрами, под ними плотный ряд одинаковых чёрных силовых элементов, текстолит чёрный матовый. Никаких логотипов и надписей. " + CLEAN + "СВЕТ: строго один источник: узкий холодный луч слева вдоль платы под пятнадцать градусов, жёсткий, 5600K, рёбра радиаторов отбрасывают длинные тени, заполняющего света нет, правый край тонет в черноте. ПЕРЕДНИЙ ПЛАН: ближние рёбра радиатора размыты до мягкой мути. СРЕДНИЙ ПЛАН: радиаторы и ряд элементов резко. ДАЛЬНИЙ ПЛАН: чёрный текстолит уходит в темноту. ПАЛИТРА строго из трёх цветов и только из них: чёрный, графит, холодное серебро. Других цветов в кадре нет. Других надписей в кадре нет. КАДР: макро, камера низко вдоль платы, горизонтальный кадр 16:9. Фотография.",
 # кадр 7 — пауза под музыку: контур, жидкость в трубках
 "f07_loop": "СУБЪЕКТ: макро прозрачной трубки кастомного водяного контура с бесцветной жидкостью, внутри медленно идут редкие мелкие пузырьки, трубка входит в медный фитинг. " + CLEAN + "СВЕТ: строго один источник: холодный белый луч сзади справа под тридцать градусов, контровой, 5600K, трубка светится по контуру, заполняющего света нет, фон уходит в чёрное. ПЕРЕДНИЙ ПЛАН: трубка крупно. ДАЛЬНИЙ ПЛАН: чёрная пустота с мягкими бликами. ПАЛИТРА строго из трёх цветов и только из них: чёрный, медь, холодный белый. Других цветов в кадре нет. Других надписей в кадре нет. КАДР: макро, фон размыт до мягкой мути, горизонтальный кадр 16:9. Фотография.",
}
log = []
for key, prompt in P.items():
    t0 = time.time()
    try:
        paths = xai.image(prompt, os.path.join(OUT, key), n=2, aspect="16:9")
        log.append({"key": key, "files": paths, "sec": round(time.time() - t0)}); print(key, "OK", [os.path.basename(p) for p in paths], round(time.time() - t0), "с")
    except Exception as e:
        log.append({"key": key, "error": str(e)}); print(key, "ERR", e)
json.dump(log, open(os.path.join(OUT, "log.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print("done")
